import React from 'react';
import { Briefcase, Clock, CheckCircle, XCircle, Gift, Calendar } from 'lucide-react';

const StatsCards = ({ stats }) => {
  const cards = [
    {
      label: 'Total Applications',
      value: stats.total || 0,
      icon: <Briefcase size={24} />,
      color: '#4f46e5',
      bg: 'linear-gradient(135deg, #eef2ff 0%, #e0e7ff 100%)'
    },
    {
      label: 'Applied',
      value: stats.applied || 0,
      icon: <Clock size={24} />,
      color: '#2563eb',
      bg: 'linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%)'
    },
    {
      label: 'Interviews',
      value: stats.interview || 0,
      icon: <Calendar size={24} />,
      color: '#d97706',
      bg: 'linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%)'
    },
    {
      label: 'Selected',
      value: stats.selected || 0,
      icon: <CheckCircle size={24} />,
      color: '#059669',
      bg: 'linear-gradient(135deg, #ecfdf5 0%, #d1fae5 100%)'
    },
    {
      label: 'Offers',
      value: stats.offer || 0,
      icon: <Gift size={24} />,
      color: '#7c3aed',
      bg: 'linear-gradient(135deg, #f5f3ff 0%, #ede9fe 100%)'
    },
    {
      label: 'Rejected',
      value: stats.rejected || 0,
      icon: <XCircle size={24} />,
      color: '#dc2626',
      bg: 'linear-gradient(135deg, #fef2f2 0%, #fee2e2 100%)'
    }
  ];

  return (
    <div className="stats-grid">
      {cards.map((card, index) => (
        <div key={index} className="stat-card" style={{ borderLeftColor: card.color }}>
          <div className="stat-icon" style={{ color: card.color, background: card.bg }}>
            {card.icon}
          </div>
          <div className="stat-info">
            <span className="stat-value" style={{ color: card.color }}>{card.value}</span>
            <span className="stat-label">{card.label}</span>
          </div>
        </div>
      ))}
    </div>
  );
};

export default StatsCards;
